// ── SHA-256 + HMAC-SHA256 + verificacion JWT, JS PURO (sandbox n8n: sin require/crypto) ──
function sha256Bytes(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const ml = bytes.length * 8;
  const withPad = bytes.slice();
  withPad.push(0x80);
  while (withPad.length % 64 !== 56) withPad.push(0);
  for (let i = 7; i >= 0; i--) withPad.push((ml / Math.pow(2, i * 8)) & 0xff);
  const rr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < withPad.length; i += 64) {
    const w = new Array(64);
    for (let j = 0; j < 16; j++) {
      w[j] = (withPad[i+j*4] << 24) | (withPad[i+j*4+1] << 16) | (withPad[i+j*4+2] << 8) | withPad[i+j*4+3];
    }
    for (let j = 16; j < 64; j++) {
      const s0 = rr(w[j-15],7) ^ rr(w[j-15],18) ^ (w[j-15] >>> 3);
      const s1 = rr(w[j-2],17) ^ rr(w[j-2],19) ^ (w[j-2] >>> 10);
      w[j] = (w[j-16] + s0 + w[j-7] + s1) | 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let j = 0; j < 64; j++) {
      const S1 = rr(e,6) ^ rr(e,11) ^ rr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[j] + w[j]) | 0;
      const S0 = rr(a,2) ^ rr(a,13) ^ rr(a,22);
      const mj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + mj) | 0;
      h=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
    }
    H = [(H[0]+a)|0,(H[1]+b)|0,(H[2]+c)|0,(H[3]+d)|0,(H[4]+e)|0,(H[5]+f)|0,(H[6]+g)|0,(H[7]+h)|0];
  }
  const out = [];
  for (const x of H) { out.push((x>>>24)&0xff,(x>>>16)&0xff,(x>>>8)&0xff,x&0xff); }
  return out;
}
function strBytes(s) { const o=[]; for (const ch of unescape(encodeURIComponent(s))) o.push(ch.charCodeAt(0)); return o; }
function hmacSha256(keyStr, msgStr) {
  let key = strBytes(keyStr);
  if (key.length > 64) key = sha256Bytes(key);
  while (key.length < 64) key.push(0);
  const ipad = key.map(b => b ^ 0x36), opad = key.map(b => b ^ 0x5c);
  return sha256Bytes(opad.concat(sha256Bytes(ipad.concat(strBytes(msgStr)))));
}
function hex(bytes) { return bytes.map(b => b.toString(16).padStart(2,'0')).join(''); }
function sha256Hex(s) { return hex(sha256Bytes(strBytes(s))); }
function b64urlFromBytes(bytes) {
  const A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  let out='';
  for (let i=0;i<bytes.length;i+=3){
    const b0=bytes[i],b1=bytes[i+1],b2=bytes[i+2];
    out+=A[b0>>2]; out+=A[((b0&3)<<4)|((b1===undefined?0:b1)>>4)];
    if(b1!==undefined){ out+=A[((b1&15)<<2)|((b2===undefined?0:b2)>>6)]; if(b2!==undefined) out+=A[b2&63]; }
  }
  return out;
}
function b64urlDecodeToStr(s) {
  const A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  let bits='', out=[];
  for (const ch of s) { const idx=A.indexOf(ch); if(idx<0) continue; bits+=idx.toString(2).padStart(6,'0'); }
  for (let i=0;i+8<=bits.length;i+=8) out.push(parseInt(bits.slice(i,i+8),2));
  return decodeURIComponent(escape(String.fromCharCode.apply(null,out)));
}
function safeEq(a,b){ if(a.length!==b.length) return false; let d=0; for(let i=0;i<a.length;i++) d|=a.charCodeAt(i)^b.charCodeAt(i); return d===0; }

function verifyJWT(token, secret, scopeRequerido) {
  if (typeof token !== 'string') return { ok:false, error:'TOKEN_AUSENTE' };
  const p = token.split('.');
  if (p.length !== 3) return { ok:false, error:'TOKEN_MALFORMADO' };
  const esperado = b64urlFromBytes(hmacSha256(secret, p[0] + '.' + p[1]));
  if (!safeEq(esperado, p[2])) return { ok:false, error:'FIRMA_INVALIDA' };
  let payload;
  try { payload = JSON.parse(b64urlDecodeToStr(p[1])); } catch(e){ return { ok:false, error:'PAYLOAD_ILEGIBLE' }; }
  const ahora = Math.floor(Date.now()/1000);
  if (!payload.exp || payload.exp <= ahora) return { ok:false, error:'TOKEN_EXPIRADO' };
  const scopes = Array.isArray(payload.scopes) ? payload.scopes : ['finanzas:read','finanzas:write'];
  if (scopeRequerido && scopes.indexOf(scopeRequerido) < 0) {
    return { ok:false, error:'SCOPE_INSUFICIENTE', requerido:scopeRequerido, tiene:scopes };
  }
  return { ok:true, actor: payload.sub || payload.username || null, nombre: payload.nombre || null, scopes: scopes, exp: payload.exp };
}

/* ── La llave de la liga se DERIVA, no se agrega al entorno ────────────────
 * Decision propia de la sesion del 27/28-sep-2026: agregar una variable nueva
 * a Railway estaba fuera de lo autorizado, y ademas una llave por proposito es
 * mejor practica que reusar la de las sesiones. Las dos cosas se resuelven
 * derivandola:
 *
 *     k = HMAC(SUITE_JWT_SECRET, 'fts-comision-aprobar-v1')
 *
 * Es separacion de llaves estandar: de `k` no se saca el secreto de las
 * sesiones, asi que una liga filtrada no compromete el login de nadie, y al
 * contrario tampoco. La etiqueta lleva version por si algun dia hay que
 * invalidar todas las ligas vivas de golpe: se sube a -v2 y se caen solas. */
function llaveLiga(secreto) {
  return hex(hmacSha256('' + secreto, 'fts-comision-aprobar-v1'));
}
/* El token son tres partes: la solicitud, un azar de 24 bytes que sale de
 * `gen_random_bytes` de Postgres (CSPRNG de verdad — el sandbox de n8n no
 * expone uno, y `Math.random` no sirve para esto), y la firma de las dos.
 *
 * La firma es lo que hace que no se pueda inventar una liga: sin `k` no se
 * puede producir un `sig` valido para ninguna solicitud, ni conociendo su id. */
function armarToken(k, sol, nonce) {
  return sol + '.' + nonce + '.' + b64urlFromBytes(hmacSha256(k, sol + '.' + nonce));
}
/* Verifica la FORMA y la FIRMA. No toca la base: eso es el segundo candado y
 * va aparte a proposito — asi una liga inventada se rechaza sin gastar una
 * consulta, y una liga bien firmada pero ya usada da un mensaje distinto. */
function abrirToken(k, token) {
  const t = '' + (token || '');
  if (!t || t.length > 300) return { ok:false, error:'LIGA_MALFORMADA' };
  const p = t.split('.');
  if (p.length !== 3) return { ok:false, error:'LIGA_MALFORMADA' };
  const sol = p[0], nonce = p[1], sig = p[2];
  if (!/^[0-9a-f-]{36}$/.test(sol))  return { ok:false, error:'LIGA_MALFORMADA' };
  if (!/^[0-9a-f]{48}$/.test(nonce)) return { ok:false, error:'LIGA_MALFORMADA' };
  const esperada = b64urlFromBytes(hmacSha256(k, sol + '.' + nonce));
  if (!safeEq(sig, esperada)) return { ok:false, error:'FIRMA_INVALIDA' };
  return { ok:true, sol: sol, nonce: nonce, huella: sha256Hex(t) };
}

/* ── Abrir la liga ─────────────────────────────────────────────────────────
 * try/catch total: la entrada es el Set del secreto (CLAUDE.md §9).
 *
 * ── POR QUE EL GET NO APRUEBA NADA ──────────────────────────────────────
 * Un GET que aprueba se dispara solo. Outlook Safe Links, los antivirus de
 * correo y los previsualizadores ABREN las ligas de un mensaje sin que nadie
 * las toque — asi que una liga de aprobacion por GET queda aprobada antes de
 * que Erick vea el correo, y sin que nadie lo decida. Es una de esas trampas
 * que no se notan porque el resultado se parece a que funciono.
 *
 * Asi que: el GET PINTA y el POST DECIDE. Lo que aprueba es el boton, no la
 * liga. Y como la pagina la sirve el mismo n8n, el POST es del mismo origen.
 *
 * ── LOS DOS CANDADOS, EN ORDEN ──────────────────────────────────────────
 * Primero la FIRMA, que no toca la base: una liga inventada se rechaza sin
 * gastar una consulta. Despues la HUELLA contra la base, que dice si esta es la
 * liga de esta solicitud y si ya se uso. Dos respuestas distintas para dos
 * cosas distintas (§20 #12b). */
try {
  const E = $input.first().json;
  const secreto = $('Set - secreto').item.json.secret;
  if (!secreto || ('' + secreto).length < 32) {
    return [{ json: { ok:false, http:500, error:'SECRETO_NO_CONFIGURADO', decidible:false,
      titulo:'No se puede comprobar la liga',
      mensaje:'Falta la configuracion del servidor. Avisale a Esteban: esto no lo arregla reintentar.' } }];
  }
  const metodo = ('' + (E.method || 'GET')).toUpperCase();
  const cuerpo = E.body || {};
  const q = E.query || {};
  const token = metodo === 'POST' ? (cuerpo.t || q.t) : q.t;

  const k = llaveLiga(secreto);
  const a = abrirToken(k, token);
  if (!a.ok) {
    return [{ json: { ok:false, http:400, error:a.error, decidible:false,
      titulo: a.error === 'FIRMA_INVALIDA' ? 'Esta liga no la emitimos nosotros' : 'Esta liga esta incompleta',
      mensaje: a.error === 'FIRMA_INVALIDA'
        ? 'La firma no cuadra. Si la copiaste a mano, puede que se haya cortado; si te llego asi por correo, no la uses y avisale a Esteban.'
        : 'Le falta una parte. Normalmente pasa cuando la liga se corta al copiarla: abrela desde el correo, sin copiarla.' } }];
  }

  /* La accion solo existe en el POST, y solo dos valores. Un tercer valor no es
   * «lo que sea»: es que algo esta mal, y se dice. */
  let accion = null, motivo = null;
  if (metodo === 'POST') {
    accion = ('' + (cuerpo.accion || '')).trim();
    if (accion !== 'aprobar' && accion !== 'rechazar') {
      return [{ json: { ok:false, http:400, error:'ACCION_INVALIDA', decidible:false,
        titulo:'No entendi que querias hacer',
        mensaje:'Vuelve a abrir la liga del correo y usa uno de los dos botones.' } }];
    }
    motivo = ('' + (cuerpo.motivo || '')).trim().slice(0, 500);
    /* Un rechazo sin motivo es un «no» que nadie puede atender: quien lo recibe
     * no sabe si falta un dato, si la persona no va, o si hay que hablarlo. El
     * CHECK de la migracion 010 tambien lo exige, asi que esto es el mensaje
     * amable de algo que la base ya no permite. */
    if (accion === 'rechazar' && motivo.length < 3) {
      return [{ json: { ok:false, http:400, error:'RECHAZO_SIN_MOTIVO', decidible:false,
        titulo:'Falta decir por que',
        mensaje:'Un rechazo sin motivo no lo puede atender nadie. Escribe una linea, aunque sea corta.' } }];
    }
  }

  const h = E.headers || {};
  return [{ json: { ok:true, metodo:metodo, accion:accion, motivo:motivo || null,
    huella:a.huella, solicitud_id:a.sol,
    /* La IP de quien abrio. `x-forwarded-for` porque n8n va detras del proxy de
     * Railway; el primer valor de la lista es el cliente. No es seguridad — una
     * liga reenviada la abre quien la reciba— pero es RASTRO, y es lo que
     * permite auditar un «yo no aprobe eso». */
    ip: ('' + (h['x-forwarded-for'] || h['x-real-ip'] || '')).split(',')[0].trim().slice(0,45) || null,
    ua: ('' + (h['user-agent'] || '')).slice(0, 250) || null } }];
} catch (e) {
  return [{ json: { ok:false, http:500, error:'FALLO_APERTURA', decidible:false,
    titulo:'No se pudo comprobar la liga',
    mensaje:'Algo fallo del lado del servidor. Vuelve a intentar en un minuto; si sigue, avisale a Esteban.' } }];
}

/* ── Que se puede hacer con esta liga ──────────────────────────────────────
 * Seis respuestas, cada una con su texto, porque son seis cosas distintas y
 * juntarlas en «liga no valida» es elegir el peor mensaje por omision (§20 #12b):
 *
 *   no existe   -> la firma era valida pero la solicitud no esta. Raro de
 *                  verdad, y se dice que es raro en vez de disimularlo.
 *   contestada  -> ya se aprobo o rechazo, con su fecha y lo que se dijo.
 *   anulada     -> se mando otra despues. La buena es la del correo mas nuevo.
 *   vencida     -> se le paso el tiempo. NADIE dijo que no; hay que volver a pedir.
 *   el beneficiario cambio -> alguien lo movio por otro lado mientras la liga viajaba.
 *   viva        -> se puede decidir. El unico caso que pinta botones.
 *
 * Una fila ausente de la consulta NO dice nada sobre su valor: solo que no
 * cumplio el filtro (§20 #18). Por eso el «no existe» se distingue del resto y
 * no se confunde con «vencida». */
const filas = $input.all().map(i => i.json).filter(f => f && f.id);
const a = $('Code - Abrir liga').first().json;
const cuando = (x) => String(x || '').slice(0,16).replace('T',' ') + ' UTC';

if (!filas.length) {
  return [{ json: { ok:false, http:404, error:'SOLICITUD_NO_EXISTE', decidible:false,
    titulo:'No encuentro esta solicitud',
    mensaje:'La firma de la liga es buena, asi que la emitimos nosotros, pero la solicitud ya no esta en la base. Es raro: avisale a Esteban con la hora a la que abriste la liga.' } }];
}
const s = filas[0];

/* El orden de estas dos importa: una solicitud ya contestada se reporta como
 * contestada aunque el tiempo tambien se le haya pasado. Al contrario seria
 * decirle «se vencio» a alguien que si aprobo — un mensaje falso. */
if (s.estado === 'aprobada' || s.estado === 'rechazada') {
  return [{ json: { ok:true, http:200, decidible:false, estado:s.estado, ben_nombre:s.ben_nombre,
    titulo: s.estado === 'aprobada' ? 'Esto ya se autorizo' : 'Esto ya se rechazo',
    mensaje: (s.estado === 'aprobada'
      ? s.ben_nombre + ' quedo autorizado el ' + cuando(s.respondido_at) + '.'
      : s.ben_nombre + ' se rechazo el ' + cuando(s.respondido_at) + ': ' + (s.motivo_rechazo || 'sin motivo escrito') + '.') +
      ' La liga es de un solo uso, asi que ya no hace nada.' } }];
}
if (s.estado === 'anulada') {
  return [{ json: { ok:true, http:200, decidible:false, estado:'anulada', ben_nombre:s.ben_nombre,
    titulo:'Esta liga ya no es la buena',
    mensaje:'Se volvio a pedir la autorizacion de ' + s.ben_nombre + ' despues de mandarte esta, asi que esta quedo sin efecto. Usa la del correo mas reciente.' } }];
}
if (s.estado === 'vencida' || s.ya_vencio === true) {
  return [{ json: { ok:true, http:200, decidible:false, estado:'vencida', ben_nombre:s.ben_nombre,
    titulo:'A esta liga se le paso el tiempo',
    mensaje:'Vencio el ' + cuando(s.vence_at) + '. Que se venza NO es un rechazo: nadie dijo que no, nadie quedo autorizado, y hay que volver a pedirla desde la cotizacion.' } }];
}
/* Y el beneficiario pudo cambiar de estado por otro lado mientras la liga
 * viajaba. Aprobar algo archivado dejaria un renglon aprobado que nadie puede
 * usar — y el CHECK de la 010 ni lo permitiria. */
if (s.ben_estado !== 'pendiente') {
  return [{ json: { ok:true, http:200, decidible:false, estado:'beneficiario_' + s.ben_estado, ben_nombre:s.ben_nombre,
    titulo: s.ben_estado === 'vigente' ? 'Ya estaba autorizado' : 'Este beneficiario ya no esta pendiente',
    mensaje: s.ben_estado === 'vigente'
      ? s.ben_nombre + ' ya aparece como autorizado por otro camino. No hace falta que hagas nada.'
      : s.ben_nombre + ' esta ' + s.ben_estado + ', asi que esta autorizacion ya no aplica.' } }];
}
return [{ json: { ok:true, http:200, decidible:true, estado:'viva',
  solicitud_id:s.id, ben_id:s.ben_id, ben_nombre:s.ben_nombre, ben_tipo:s.ben_tipo,
  ben_motivo:s.ben_motivo, odoo_cuenta_id:s.odoo_cuenta_id, pedido_a:s.pedido_a,
  pedido_por:s.pedido_por, pedido_at:s.pedido_at, vence_at:s.vence_at,
  metodo:a.metodo, accion:a.accion, motivo:a.motivo, ip:a.ip, ua:a.ua, huella:a.huella } }];

/* ── Lo que de verdad paso ─────────────────────────────────────────────────
 * Se lee el CONTADOR de filas tocadas, no el «no hubo error». Cero filas con
 * cero error es exactamente como se ve un segundo clic — y tambien como se ve
 * una liga que vencio entre que se pinto la pagina y que se apreto el boton.
 * Un `insertadas: 0` se parece a un exito (§9), asi que aqui se exige == 1. */
const r = $input.first().json || {};
const ev = $('Code - Evaluar').first().json;
const a = $('Code - Abrir liga').first().json;

if (Number(r.solicitudes_tocadas) !== 1) {
  return [{ json: { ok:false, http:409, decidible:false, error:'YA_NO_SE_PODIA',
    titulo:'No alcance a guardarlo',
    mensaje:'Entre que se abrio la pagina y que apretaste el boton, esta liga dejo de servir: o alguien ya la contesto, o se le paso el tiempo. Vuelve a abrirla desde el correo para ver como quedo.',
    crudo: { solicitudes_tocadas: r.solicitudes_tocadas || 0 } } }];
}
/* Y el gemelo: la solicitud si cambio y el beneficiario NO. Solo puede pasar si
 * alguien lo movio por otro lado en el mismo instante. No se puede deshacer
 * desde aqui sin adivinar, asi que se DICE — con los dos numeros crudos, que es
 * lo que permite arreglarlo a mano sin reconstruir la historia. */
if (Number(r.beneficiarios_tocados) !== 1) {
  return [{ json: { ok:false, http:409, decidible:false, error:'CATALOGO_NO_CUADRO',
    titulo:'Se guardo tu respuesta pero el catalogo no la tomo',
    mensaje:'Tu respuesta quedo escrita, pero el beneficiario ya no estaba pendiente cuando se intento marcar, asi que el catalogo NO cambio. Avisale a Esteban: hay que revisarlo a mano.',
    crudo: { solicitudes_tocadas: r.solicitudes_tocadas, beneficiarios_tocados: r.beneficiarios_tocados,
             solicitud_estado: r.solicitud_estado, ben_estado: r.ben_estado } } }];
}
const aprobo = a.accion === 'aprobar';
return [{ json: { ok:true, http:200, decidible:false, hecho:true,
  accion: a.accion, estado: r.solicitud_estado, ben_estado: r.ben_estado,
  ben_nombre: r.ben_nombre || ev.ben_nombre, respondido_at: r.respondido_at,
  motivo: a.motivo || null, odoo_cuenta_id: ev.odoo_cuenta_id, pedido_por: ev.pedido_por,
  titulo: aprobo ? 'Listo, quedo autorizado' : 'Listo, quedo rechazado',
  mensaje: aprobo
    ? (r.ben_nombre || ev.ben_nombre) + ' ya puede aparecer como beneficiario de comision. Recuerda: esto NO autorizo ningun pago.'
    : (r.ben_nombre || ev.ben_nombre) + ' no queda autorizado. Se le avisa a quien lo pidio, con tu motivo.',
  crudo: { solicitudes_tocadas: r.solicitudes_tocadas, beneficiarios_tocados: r.beneficiarios_tocados } } }];

/* El acuse a quien lo pidio, y la copia a Esteban al aprobarse — que es lo que
 * pide el punto C del #294.
 *
 * A quien le toca saberlo: quien lo pidio SIEMPRE; Esteban SOLO al aprobarse. Un
 * rechazo no le llega porque no cambia nada que el tenga que atender — y un
 * correo que no hay que atender es como se ensena a la gente a filtrar los que si.
 *
 * MODO_PRUEBA hace lo mismo que en comision-pedir: todo a sales@fts.mx y a nadie
 * mas, con los destinatarios de verdad calculados y visibles en la respuesta
 * para poder ver a donde HABRIAN ido. */
const MODO_PRUEBA = true;
const BUZON_PRUEBA = 'sales@fts.mx';
const COPIA_CEO = 'estebandelacruz@fts.mx';

const d = $('Code - Resuelto').first().json;
const ev = $('Code - Evaluar').first().json;
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const aprobo = d.accion === 'aprobar';

/* El correo de quien lo pidio se arma del actor de la suite. Es una suposicion
 * —que el usuario de la suite es el buzon de FTS— y por eso va marcada: el dia
 * que haya un usuario cuyo correo no siga ese patron, esto manda a un buzon que
 * no existe. Cuando el padron de usuarios guarde el correo, se lee de ahi. */
const reales = [ ('' + (ev.pedido_por || '')).indexOf('@') >= 0 ? ev.pedido_por : (ev.pedido_por + '@fts.mx') ];
if (aprobo) reales.push(COPIA_CEO);

const html =
  '<div style="font:14px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1c1c1c;max-width:560px">' +
  '<p style="margin:0 0 14px"><strong>' + esc(d.ben_nombre) + '</strong> ' +
  (aprobo ? 'quedo <strong>autorizado</strong> como beneficiario de comision.'
          : 'fue <strong>rechazado</strong> como beneficiario de comision.') + '</p>' +
  '<table style="border-collapse:collapse;margin:0 0 16px">' +
  '<tr><td style="padding:3px 12px 3px 0;color:#6b6b6b">Cuando</td><td style="padding:3px 0">' +
    esc(String(d.respondido_at || '').slice(0,16).replace('T',' ')) + ' UTC</td></tr>' +
  '<tr><td style="padding:3px 12px 3px 0;color:#6b6b6b">Lo pidio</td><td style="padding:3px 0">' + esc(ev.pedido_por) + '</td></tr>' +
  (d.motivo ? '<tr><td style="padding:3px 12px 3px 0;color:#6b6b6b">Motivo</td><td style="padding:3px 0">' + esc(d.motivo) + '</td></tr>' : '') +
  '</table>' +
  (aprobo
    ? '<div style="background:#f6f7f8;border-left:3px solid #1a7f37;padding:10px 14px;margin:0 0 14px">' +
      '<strong>Esto no autorizo ningun pago.</strong> Autorizo que pueda aparecer como beneficiario. ' +
      'Ya se puede confirmar la orden donde sale.</div>'
    : '<div style="background:#f6f7f8;border-left:3px solid #cf222e;padding:10px 14px;margin:0 0 14px">' +
      'La orden donde aparece <strong>sigue sin poder confirmarse</strong> mientras este beneficiario ' +
      'este ahi. Hay que quitarlo, o volver a pedirlo con lo que falta.</div>') +
  (MODO_PRUEBA ? '<p style="margin:0 0 6px;padding:8px 12px;background:#fff8c5;font-size:12px">MODO PRUEBA: ' +
    'esto habria ido a ' + esc(reales.join(', ')) + '.</p>' : '') +
  '<p style="margin:0;color:#6b6b6b;font-size:12px">FTS Suite &middot; modulo comercial</p>' +
  '</div>';

const para = MODO_PRUEBA ? [BUZON_PRUEBA] : reales;
return [{ json: {
  message: {
    subject: '[FTS] Beneficiario de comision ' + (aprobo ? 'autorizado' : 'rechazado') + ': ' +
             d.ben_nombre + (MODO_PRUEBA ? ' (PRUEBA)' : ''),
    body: { contentType: 'HTML', content: html },
    toRecipients: para.map(x => ({ emailAddress: { address: x } }))
  },
  saveToSentItems: true,
  _para: para, _para_real: reales, _modo_prueba: MODO_PRUEBA
} }];
